    description_longue: "En février 1848, à Londres, Karl Marx (29 ans) et Friedrich Engels (27 ans) publient un court texte de commande, rédigé pour la Ligue des communistes. Le Manifeste analyse l'histoire comme une succession de luttes de classes et prédit que la bourgeoisie, en développant le capitalisme industriel, crée elle-même son fossoyeur : le prolétariat. Le texte se termine par le célèbre appel « Prolétaires de tous les pays, unissez-vous ! ». Publié quelques jours avant les révolutions de 1848 qui embrasent l'Europe, il passe presque inaperçu à sa sortie mais deviendra, dans les décennies suivantes, l'un des textes politiques les plus diffusés et les plus influents de l'histoire.",
