    description_longue: "Dans la nuit du 25 au 26 octobre 1917 (7-8 novembre dans le calendrier grégorien), les Bolchéviques, dirigés par Lénine et organisés militairement par Trotski, s'emparent des points stratégiques de Petrograd et prennent d'assaut le Palais d'Hiver, siège du gouvernement provisoire dirigé par Kerenski. Contrairement à l'image d'un assaut massif et sanglant popularisée par la propagande soviétique ultérieure (notamment le film d'Eisenstein), la prise du pouvoir se fait avec une résistance relativement limitée, le gouvernement provisoire étant déjà largement discrédité. Le lendemain, le IIe Congrès des Soviets ratifie la prise du pouvoir et adopte les décrets sur la paix et sur la terre, deux mesures immédiatement populaires.",
