    description_longue: "Après la victoire électorale du Front populaire (coalition de gauche) en mai 1936, une vague spontanée de grèves avec occupation d'usines déferle sur la France, impliquant plus de deux millions de travailleurs. Sous la pression de ce mouvement social sans précédent, le gouvernement de Léon Blum négocie avec le patronat les accords de Matignon, qui instaurent notamment les premiers congés payés (deux semaines), la semaine de 40 heures et la généralisation des conventions collectives. Ces avancées sociales majeures transforment durablement les conditions de vie des travailleurs français et restent, encore aujourd'hui, des acquis sociaux emblématiques.",
