    description_longue: "À partir de mars 1793, les paysans de Vendée se soulèvent contre la Révolution française, notamment en réaction à la conscription forcée décrétée pour alimenter les armées révolutionnaires, mais aussi en défense de la religion catholique et de la royauté face à la déchristianisation imposée par les révolutionnaires. Le conflit dégénère en guerre civile d'une extrême violence, marquée par des massacres de masse des deux côtés, notamment les « colonnes infernales » envoyées par la Convention en représailles. Le bilan humain reste débattu, certains historiens évoquant jusqu'à plusieurs centaines de milliers de morts, incluant les victimes civiles, un épisode que certains qualifient de « génocide vendéen », terme toutefois contesté par une partie des historiens.",
