    description_longue: "En 1848, une vague de révolutions embrase simultanément la France, les États allemands, l'Empire autrichien, l'Italie et la Hongrie, mêlant revendications libérales (constitutions, suffrage élargi), nationales (unification allemande et italienne, indépendance hongroise) et sociales (conditions ouvrières, journée de travail). En France, la révolution de février renverse la monarchie de Juillet et instaure la Deuxième République, qui proclame le suffrage universel masculin et abolit à nouveau l'esclavage. La plupart de ces révolutions échouent finalement à court terme, les monarchies reprenant le contrôle dès 1849, mais elles posent les bases idéologiques et sociales des transformations politiques du reste du siècle.",
