    description_longue: "Le 15 janvier 1919, après l'échec de l'insurrection spartakiste, Rosa Luxembourg (47 ans) et Karl Liebknecht (47 ans également) sont arrêtés à Berlin par des membres des corps francs (Freikorps), milices paramilitaires nationalistes agissant avec l'aval tacite du gouvernement social-démocrate. Liebknecht est abattu le soir même, officiellement « en tentant de s'échapper » - une version largement remise en question par les historiens. Luxembourg est frappée à coups de crosse puis abattue d'une balle dans la tête ; son corps est jeté dans le canal de Landwehr, où il ne sera retrouvé que plusieurs mois plus tard. Ces assassinats, restés largement impunis, marquent une rupture profonde et durable entre communistes et sociaux-démocrates en Allemagne, aux conséquences politiques majeures pour la suite de l'histoire allemande, notamment face à la montée ultérieure du nazisme.",
