    description_longue: "Votée article par article du 20 au 26 août 1789 par l'Assemblée nationale constituante, la Déclaration des droits de l'homme et du citoyen proclame en 17 articles des principes fondamentaux : liberté, égalité devant la loi, propriété, sûreté et résistance à l'oppression. Rédigée dans le sillage immédiat de la prise de la Bastille, elle marque une rupture radicale avec la monarchie absolue et l'ordre des privilèges de l'Ancien Régime. Par son ambition universelle, revendiquée dès son préambule, elle dépasse le seul cadre national et inspirera directement, plus d'un siècle et demi plus tard, la Déclaration universelle des droits de l'homme adoptée par l'ONU en 1948.",
